// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Insects".

I decided to work with just a few geometric shapes. Ultimately,
I needed a cube, a disc, a capsule and a sphere. To keep things
simple and because I like the reflections it produces, I opted
for a waffle pattern for the facets of the eyes and the scales
on the wings. I then used a smooth union to create organic transitions.

I also gave the little creature some well-developed muscles on its back.
In my imagination, all these super-strong insects meet at the gym to
work out every other day. Arnold Fly! (If you know what I mean).

I was finally able to do without the WebGL 2 polyfills by updating
to the latest version of p5.js. Dave Pagurek was the one who gave me
that tip.

This tip motivated me to rethink the CSS injection I used to control 
the resolution of the shader. Dave helped me with that too.
Thank you very much, Dave! Thanks also to the Birb's Nest community.
Community is priceless!
*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2691522/files/vert.glsl', 'frag.glsl');
}

function setup() {
	pixelDensity(scale)
  createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
  resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader);
  theShader.setUniform("resolution", [width * scale, height * scale]);
  theShader.setUniform("time", millis() / 1000.0);
  theShader.setUniform("touch", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * scale, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) * scale, 0, height * scale, height * scale, 0)]);
  theShader.setUniform("pointerCount", ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) ? 1 : 0);
  rect(0, 0, width, height);
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 touch;
uniform int pointerCount;
#define mouse (touch/R)
#define P pointerCount
#define FC gl_FragCoord.xy
#define R resolution
#define T (-.5+time)
#define S smoothstep
#define N normalize
#define MN min(R.x,R.y)
#define PRECI 1e-3
#define SIN sin
#define FLAP SIN(T*5.)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
#define procd (T*.1)
#define scene int(floor(mod(procd, 11.)))
#define light pow(S(.0,1.,sin(-1.57+6.28318*fract(procd))*.5+.5),.4)
struct Material {
	float dist;
	vec3 col;
	float rough;
	float preci;
	bool hit;
};
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
Material matmin(Material a, Material b) {
	if (a.dist<b.dist) return a;
	return b;
}
Material matsmin(Material a, Material b, float k) {
	Material r=matmin(a,b);
	r.dist=smin(a.dist,b.dist,k);
	return r;
}
Material matsmax(Material a, Material b, float k) {
	Material r=matmin(a,b);
	r.dist=smin(a.dist,-b.dist,-k);
	return r;
}
float bmap( vec3 p ) {
	p=vec3(p.x+p.z*.5, p.y, p.x-p.z);
	p=vec3(p.x+p.y, p.x-p.y, p.z);
	p=fract(p*3.99);
	float d=length(p-.5);
	d=d*d;
	return -d*4e-3;
}
float box(vec3 p, vec3 s) {
	p=abs(p)-s;
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z));
}
Material eyes(vec3 p) {
	p.x=abs(p.x)-.8;
	float k=bmap(p*2.), d=length(p)-1.1;
	return Material(d+k, mix(hue(-.9*-p.y),hue(-.9*log(d*d)),.05), .3, PRECI, false);
}
Material nose(vec3 p) {
	p.z-=.5;
	p.y+=.2;
	float d=length(p)-1.5;
	d=smin(d,(dot(p,vec3(0,-.2,1))-.7),-.5);
	d=smin(d,length(p)-1.,.5);
	Material a=Material(length(p-vec3(0,0,-.55))-1.2,hue(p.y*abs(p)/dot(p,p)),.8, PRECI, false);
	p.x=abs(p.x)-.3;
	p.xz*=rot(-.2+.03*SIN(T)+FLAP*.02);
	p.yz*=rot(p.y*.3*(1.+FLAP*.05)+.01*SIN(T));
	p.y-=clamp(p.y,1.0,4.2);
	d=smin(d,length(p)-.05,.3);
	a=matmin(a,Material(d*.4,hue(-S(1.,.0,abs(p.x*1.4))),.9, PRECI, false));
	return a;
}
Material head(vec3 p) {
	p.z+=.25+FLAP*.05;
	p.yz*=rot(.1*SIN(floor(T))-FLAP*.0125);
	p.xz*=rot(.1*SIN(floor(T*.2)));
	Material a=eyes(p),
	b=nose(p);
	b=matsmax(b,a,.1);
	a=matmin(a,b);
	return a;
}
Material chest(vec3 p) {
	p.z-=2.5;
	p.y+=.2;
	float e=FLAP*.1;
	p.y*=S(.0,.65*S(-1.0,1.,p.y),clamp((e*.5+.5)+.3*e*(.5+.5*sin(T)),.0,1.));
	p.z*=1.+S(.0,1.,-.25*SIN(p.y*1.3));
	p.x*=1.+S(.0,1.,-.65*SIN(5.5+p.y+e));
	p.xz*=S(.2,.87,1.-e);
	float d=length(p)-1.3*(1.+e*.3);
	d=smin(d,box(p,vec3(1,.9,.7)),1.2);
	return Material(d, hue(p.y*abs(p)/(dot(p,p))), .9, PRECI,  false);
}
Material abdomen(vec3 p) {
	p.z-=5.7-.0125*SIN(T*10.)+FLAP*.03;
	p.yz*=rot(.2-(.4+.0125*SIN(T*10.))*p.z*(1.+FLAP*.01))*rot(-.5-FLAP*.05);
	p.x*=1.8;
	p.y*=3.;
	p.y+=FLAP*.4;
	float d=length(p)-2.5;
	return Material(d*.3, hue(.6*p.y-exp(-log2(sqrt(abs(p)))*.2)), .6, PRECI, false);
}
Material wings(vec3 p) {
	p.y-=.7;
	p.z-=2.1;
	p.z=-p.z;
	p.x=abs(p.x);
	float e=FLAP*.6-.4;
	mat2 m=rot(log2(pow(1.+abs(p.x),3.+(1.*18.*(.5+.5*sin(T)))))*e*.01);
	p.xy*=m;
	p.xz*=.2;
	float t=atan(p.x,p.z),
	s=(sin(t*p.x*1.3-1.4)*.9+sin(t*p.x-.3)*.3)-length(p.xz);
	p.xy*=rot(.2*e)*rot(.4*e);
	vec2 c=vec2(abs(s)-1.,abs(p.y)-.01);
	float d=length(max(c,.0))-min(.0,max(c.x,c.y))-.002;
	d-=bmap(p*8.)*.6;
	return Material(d*.4, max(hue(.3-log2(sqrt(s+1.))),hue(s)), .6, 5e-5, false);
}
Material legs(vec3 p) {
	p.zy*=rot(p.x*.03);
	p.z-=2.5;
	p.y+=2.5;
	vec3 q=p;
	q.x=abs(q.x)-.5;
	float id=floor(p.z*1.5+.5)/3.;
	q.z-=clamp(round(q.z*1.5),-1.,1.)/1.5;
	q.xz=q.zx;
	q.y-=1.;
	q.yz*=rot(.2-.2*(SIN(.04+id*T*.2+(T+id*3.))*.5+.5)-FLAP*.05);
	q.yz*=rot(.2);
	q.xz*=rot(SIN(id+q.y*3.)*.005);
	q.y+=1.;
	vec3 st=q;
	st.y-=clamp(st.y,.0,1.);
	float d=length(st)-.2;
	q.yz*=rot(1.8*(1.+FLAP*.05));
	st=q;
	st.y+=2.;
	q.y-=clamp(q.y,-2.,.0);
	d=smin(d,length(q)-.15,.3);
	st.yz*=rot(-.9*(1.+FLAP*.05));
	st.y-=clamp(st.y,-2.5,.0);
	d=smin(d,length(st)-.1,.2);
	return Material(d*.4, hue(-1.2+.2*abs(p.x*.2)), 1., PRECI, false);
}
Material map(vec3 p) {
	p.z+=2.5;
	Material a=chest(p), 
	b=wings(p);
	a=matsmin(a,b,.1+.1*sin(6.28318*abs(p.x)));
	b=legs(p);
	a=matsmin(a,b,.3+.1*sin(12.*abs(p.x)));
	b=head(p);
	a=matmin(a,b);
	b=abdomen(p);
	a=matmin(a,b);
	return a;
}
Material march(inout vec3 p, vec3 rd) {
	Material mat;
	float dd=.0;
	for (int i; i++<1200;) {
		mat=map(p);
		if (abs(mat.dist)<1e-3) {
			mat.hit=true;
			break;
		}
		if (dd>25.) break;
		p+=rd*mat.dist;
		dd+=mat.dist;
	}
	return mat;
}
vec3 norm(vec3 p, float h) {
	vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h).dist+
		k.yxy*map(p+k.yxy*h).dist+
		k.yyx*map(p+k.yyx*h).dist+
		k.xxx*map(p+k.xxx*h).dist
	);
}
vec3 render(inout vec3 p, vec3 rd, vec3 lp) {
	vec3 col=vec3(0);
	Material mat=march(p,rd);
	if (mat.hit) {
		vec3 n=norm(p,mat.preci), l=N(lp-p);
		float dif=clamp(dot(l,n),.0,1.),
		fres=pow(clamp(1.+dot(rd,n),.0,1.),5.),
		spec=S(1.,.0,mat.rough)*pow(clamp(dot(reflect(rd,n),l),.0,1.),8.),
		ld=max(distance(lp,p),1e-3),
		sh=S(.0,1.,map(p+lp*2.).dist/2.);
		col+=clamp(.6*mat.col+.4*S(.3,1.,sh*sqrt(dif))*mat.col,.0,1.);
		col+=clamp(spec*vec3(1,.95,.8)+spec*.5,.0,1.);
		col+=fres*vec3(1,.95,.8);
		col*=1./(1.+ld*125e-4+ld*ld*5e-3);
	} else {
		col=sqrt(hue(2.8+dot(rd,rd)));
	}
	return col;
}
void cam(inout vec3 p) {
	int sc=P>0?-1:scene;
	float yz=-mouse.y*6.3+3.14, xz=3.14-mouse.x*6.3;
	switch (sc) {
		case 0:
			yz=1.3;
			xz=2.7;
			break;
		case 1:
			yz=-.5;
			xz=-.3;
			break;
		case 2:
			yz=-.5;
			xz=1.3+T*.2;
			break;
		case 3:
			yz=-.5;
			xz=.3;
			break;
		case 4:
			yz=-1.;
			xz=.0;
			break;
		case 5:
			yz=.5;
			xz=2.4;
			break;
		case 6:
			yz=.5;
			xz=.4;
			break;
		case 7:
			yz=-.5;
			xz=-.4;
			break;
		case 8:
			yz=-.5;
			xz=-3.4;
			break;
		case 9:
			yz=.5;
			xz=3.4;
			break;
		case 10:
			yz=.85;
			xz=.4;
			break;
	}
	p.yz*=rot(yz);
	p.xz*=rot(xz);
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,-15), lp=vec3(1,3,-5),
	rd=N(vec3(uv,1));
	cam(p); cam(rd); cam(lp);
	col+=render(p,rd,lp);
	col=mix(vec3(1),col,min(S(.0,1.,time*.3),1.)*(P>0?1.:light));
	uv=.6*(FC/R*2.-1.);
	col=mix(col,vec3(0),pow(dot(uv,uv),.8));
	O=vec4(col,1);
}

